mapper.update:
UPDATE payment_order
SET cashier_id = #{cashierId}, update_time = NOW()
WHERE id = #{id}

mapper.select:
SELECT order_type, pay_method, COUNT(*) AS order_count, SUM(amount) AS total_amount
FROM payment_order
WHERE status = 'PAID'
  AND pay_time >= #{start}
  AND pay_time < #{end}
GROUP BY order_type, pay_method

mapper.update:
UPDATE payment_order
SET settle_flag = 1, update_time = NOW()
WHERE status = 'PAID'
  AND settle_flag = 0
  AND cashier_id = #{cashierId}
  AND pay_time >= #{start}
  AND pay_time < #{end}
